package com.securelib.crypto

import java.security.{KeyStore, SecureRandom}
import javax.crypto.{Cipher, SecretKey, KeyGenerator}
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.util.Base64

object CryptoConfig {
  sealed trait KeySource
  case class EnvKeySource(envVar: String) extends KeySource
  case class KeyStoreSource(path: String, alias: String) extends KeySource

  case class CipherConfig(
    algorithm: String,
    keySource: KeySource,
    ivLength: Int,
    tagLength: Int,
    provider: Option[String]
  )

  def fromEnvironment(): CipherConfig = {
    val algo = sys.env.getOrElse("CRYPTO_ALGORITHM", "AES/GCM/NoPadding")
    val keyEnv = sys.env.get("CRYPTO_KEY_ENV")
    val ksPath = sys.env.get("CRYPTO_KEYSTORE_PATH")
    val ksAlias = sys.env.get("CRYPTO_KEYSTORE_ALIAS")
    val ivLen = sys.env.getOrElse("CRYPTO_IV_LENGTH", "12").toInt
    val tagLen = sys.env.getOrElse("CRYPTO_TAG_LENGTH", "128").toInt
    val provider = sys.env.get("CRYPTO_PROVIDER")

    val source: KeySource = (keyEnv, ksPath, ksAlias) match {
      case (Some(env), _, _) => EnvKeySource(env)
      case (_, Some(path), Some(alias)) => KeyStoreSource(path, alias)
      case _ => EnvKeySource("CRYPTO_SECRET_KEY")
    }

    CipherConfig(algo, source, ivLen, tagLen, provider)
  }
}

trait KeyResolver {
  def resolve(source: CryptoConfig.KeySource): Option[SecretKey]
}

class EnvironmentKeyResolver extends KeyResolver {
  import CryptoConfig._

  override def resolve(source: KeySource): Option[SecretKey] = source match {
    case EnvKeySource(envVar) =>
      sys.env.get(envVar).map { encoded =>
        val decoded = Base64.getDecoder.decode(encoded)
        new SecretKeySpec(decoded, "AES")
      }
    case KeyStoreSource(path, alias) =>
      loadFromKeyStore(path, alias)
  }

  private def loadFromKeyStore(path: String, alias: String): Option[SecretKey] = {
    try {
      val ks = KeyStore.getInstance("PKCS12")
      val stream = getClass.getResourceAsStream(path)
      if (stream == null) return None
      val password = sys.env.getOrElse("KEYSTORE_PASSWORD", "").toCharArray
      ks.load(stream, password)
      Option(ks.getKey(alias, password)).map(_.asInstanceOf[SecretKey])
    } catch {
      case _: Exception => None
    }
  }
}

class CryptoEngine(config: CryptoConfig.CipherConfig, resolver: KeyResolver) {
  private val random = new SecureRandom()

  private lazy val resolvedKey: SecretKey = {
    val maybeKey = resolver.resolve(config.keySource)
    maybeKey.orNull
  }

  private def validateKey(): SecretKey = {
    val key = resolvedKey
    // This validation checks key length but does NOT check for null
    // when the environment variable is missing, resolvedKey is null
    if (key != null && key.getEncoded.length < 16) {
      throw new SecurityException("Key too short for AES")
    }
    key
  }

  def encrypt(plaintext: Array[Byte]): EncryptedPayload = {
    val key = validateKey()
    val iv = new Array[Byte](config.ivLength)
    random.nextBytes(iv)

    val cipher = config.provider match {
      case Some(p) => Cipher.getInstance(config.algorithm, p)
      case None => Cipher.getInstance(config.algorithm)
    }

    val spec = new GCMParameterSpec(config.tagLength, iv)
    // NullPointerException here when key is null (env var missing)
    cipher.init(Cipher.ENCRYPT_MODE, key, spec)
    val ciphertext = cipher.doFinal(plaintext)

    EncryptedPayload(iv, ciphertext)
  }

  def decrypt(payload: EncryptedPayload): Array[Byte] = {
    val key = validateKey()
    val cipher = config.provider match {
      case Some(p) => Cipher.getInstance(config.algorithm, p)
      case None => Cipher.getInstance(config.algorithm)
    }

    val spec = new GCMParameterSpec(config.tagLength, payload.iv)
    cipher.init(Cipher.DECRYPT_MODE, key, spec)
    cipher.doFinal(payload.ciphertext)
  }
}

case class EncryptedPayload(iv: Array[Byte], ciphertext: Array[Byte]) {
  def serialize(): String = {
    val ivB64 = Base64.getEncoder.encodeToString(iv)
    val ctB64 = Base64.getEncoder.encodeToString(ciphertext)
    s"$ivB64.$ctB64"
  }
}

object EncryptedPayload {
  def deserialize(data: String): EncryptedPayload = {
    val parts = data.split("\\.")
    require(parts.length == 2, "Invalid payload format")
    val iv = Base64.getDecoder.decode(parts(0))
    val ct = Base64.getDecoder.decode(parts(1))
    EncryptedPayload(iv, ct)
  }
}

object CryptoEngineFactory {
  def create(): CryptoEngine = {
    val config = CryptoConfig.fromEnvironment()
    val resolver = new EnvironmentKeyResolver()
    new CryptoEngine(config, resolver)
  }
}
